var plugin=(()=>{
  const getSession=()=>null;
  const AbortSignal={timeout(ms){const controller=new AbortController();setTimeout(()=>controller.abort(),ms);return controller.signal;}};
  async function safeFetch(url,opts={}){
    const value=await new Promise((resolve,reject)=>{
      const signal=opts.signal,abort=()=>reject(new Error("Adaptation request aborted"));
      if(signal?.aborted){abort();return;}
      signal?.addEventListener("abort",abort,{once:true});
      harbor.http(String(url),{method:opts.method??"GET",headers:opts.headers??{},body:opts.body,responseType:"text",timeoutMs:12000})
        .then(value=>{signal?.removeEventListener("abort",abort);resolve(value);},error=>{signal?.removeEventListener("abort",abort);reject(error);});
    });
    return {ok:value.ok===true,status:value.status,headers:{get(name){return Object.entries(value.headers??{}).find(([key])=>key.toLowerCase()===name.toLowerCase())?.[1]??null;}},text:async()=>String(value.body??""),json:async()=>JSON.parse(String(value.body??""))};
  }
  "use strict";
const ANILIST_GRAPHQL_URL = "https://graphql.anilist.co";
"use strict";
class AnilistApiError extends Error {
    constructor(status, body) {
        super(`AniList HTTP ${status}: ${body.slice(0, 200)}`);
        this.status = status;
        this.body = body;
    }
    get isAuthenticationError() {
        if (this.status === 401)
            return true;
        if (this.status !== 400 && this.status !== 200)
            return false;
        let messages = [this.body];
        try {
            const parsed = JSON.parse(this.body);
            messages = parsed.errors?.map((error) => error.message ?? "") ?? [];
        }
        catch { /* GraphQL errors may already be reduced to their message. */ }
        return messages.some(message => /^(invalid token|token (?:has )?expired|unauthenticated)\.?$/i.test(message.trim()));
    }
}
"use strict";
function doFetch(query, variables, token) {
    const headers = {
        "Content-Type": "application/json",
        Accept: "application/json",
    };
    if (token)
        headers["Authorization"] = `Bearer ${token}`;
    return safeFetch(ANILIST_GRAPHQL_URL, {
        method: "POST",
        signal: AbortSignal.timeout(15000),
        headers,
        body: JSON.stringify({ query, variables }),
    });
}
async function anilistRequest(query, variables = {}, accessToken, skipAuth = false) {
    const token = skipAuth ? null : (accessToken ?? getSession()?.accessToken ?? null);
    let res = await doFetch(query, variables, token);
    if (res.status === 429) {
        const retry = Number(res.headers.get("retry-after") ?? "1");
        const waitMs = (Number.isFinite(retry) ? Math.min(Math.max(retry, 1), 30) : 1) * 1000;
        await new Promise((r) => setTimeout(r, waitMs));
        res = await doFetch(query, variables, token);
    }
    if (!res.ok) {
        const body = await res.text().catch(() => "");
        throw new AnilistApiError(res.status, body);
    }
    const json = (await res.json());
    if (json.errors && json.errors.length > 0) {
        throw new AnilistApiError(200, json.errors.map((e) => e.message).join("; "));
    }
    if (!json.data)
        throw new AnilistApiError(200, "Missing GraphQL data");
    return json.data;
}

  const anilistAnimeSearch=(()=>{"use strict";
const SEARCH_QUERY = `query ($q: String, $perPage: Int) {
  Page(perPage: $perPage) {
    media(search: $q, type: ANIME, sort: SEARCH_MATCH) {
      id
      idMal
      format
      title { romaji english }
      coverImage { extraLarge large }
      bannerImage
      seasonYear
      averageScore
      description
      countryOfOrigin
    }
  }
}`;
async function anilistAnimeSearch(query, perPage = 8) {
    const q = query.trim();
    if (q.length < 2)
        return [];
    try {
        const data = await anilistRequest(SEARCH_QUERY, { q, perPage }, undefined, true);
        return (data?.Page?.media ?? []).map((m) => ({
            anilistId: m.id,
            malId: m.idMal ?? null,
            format: m.format ?? null,
            name: m.title.english?.trim() || m.title.romaji?.trim() || "Untitled",
            year: m.seasonYear ? String(m.seasonYear) : null,
            poster: m.coverImage?.large ?? m.coverImage?.extraLarge ?? null,
            background: m.bannerImage ?? null,
            overview: (m.description ?? "").replace(/<[^>]+>/g, "").trim(),
            score: m.averageScore ? m.averageScore / 10 : 0,
        }));
    }
    catch {
        return [];
    }
}
return anilistAnimeSearch;})();
  const animeCatalogRequest=(()=>{"use strict";
const ANIME_CATALOG_BASE = "https://api.tenrai.org/v1";
const ANIME_CATALOG_FALLBACK = "https://jikanfortheweebs.midnightignite.me/v4";
function catalogRetryDelay(value, now) {
    const seconds = value === null ? NaN : Number(value);
    const delay = Number.isFinite(seconds) ? seconds * 1000 : Date.parse(value ?? "") - now;
    return Number.isFinite(delay) ? Math.max(550, delay) : 2000;
}
function createAnimeCatalogClient(options = {}) {
    const request = options.fetch ?? ((...args) => fetch(...args));
    const now = options.now ?? Date.now;
    const sleep = options.sleep ?? ((ms) => new Promise(resolve => setTimeout(resolve, ms)));
    const timeout = options.timeoutMs ?? 12000, cooldown = options.cooldownMs ?? 60000;
    const providers = [
        { base: ANIME_CATALOG_BASE, fetch: request, interval: options.intervalMs ?? 550, nextStart: 0, unavailableUntil: 0 },
        // Midnight's public cache-miss budget is 60/minute, lower than Tenrai's.
        { base: ANIME_CATALOG_FALLBACK, fetch: options.fallbackFetch ?? request, interval: options.fallbackIntervalMs ?? 1100, nextStart: 0, unavailableUntil: 0 },
    ];
    let queue = Promise.resolve();
    let lastError = new Error("Anime catalogs temporarily unavailable");
    const inflight = new Map();
    return function catalogRequest(path) {
        if (!/^\/(?:anime|top\/anime|seasons)(?:[/?]|$)/.test(path) || path.includes("..")) {
            return Promise.reject(new Error("Invalid anime catalog path"));
        }
        const existing = inflight.get(path);
        if (existing)
            return existing;
        const pending = queue.then(async () => {
            for (const provider of providers) {
                // One dead provider must not add another timeout to every queued row.
                if (provider.unavailableUntil > now())
                    continue;
                if (provider.nextStart > now())
                    await sleep(provider.nextStart - now());
                const controller = new AbortController();
                // Queue time never consumes the request's network timeout.
                const timer = setTimeout(() => controller.abort(), timeout);
                let retry = cooldown;
                try {
                    const response = await provider.fetch(`${provider.base}${path}`, {
                        signal: controller.signal, credentials: "omit", headers: { Accept: "application/json" },
                    });
                    if (response.status === 429) {
                        retry = catalogRetryDelay(response.headers.get("retry-after"), now());
                    }
                    // A missing title or invalid query says nothing about provider health.
                    if ([400, 404, 422].includes(response.status))
                        retry = 0;
                    if (!response.ok) {
                        throw new Error(`Anime catalog HTTP ${response.status}`);
                    }
                    const payload = await response.json();
                    if (!payload || typeof payload !== "object" || !("data" in payload) || payload.data == null) {
                        throw new Error("Invalid anime catalog response");
                    }
                    const detail = /^\/anime\/\d+(?:\/full)?(?:\?|$)/.test(path);
                    if (detail ? (Array.isArray(payload.data) || typeof payload.data !== "object" || !("mal_id" in payload.data)) : !Array.isArray(payload.data)) {
                        throw new Error("Invalid anime catalog data");
                    }
                    provider.unavailableUntil = 0;
                    return payload;
                }
                catch (error) {
                    lastError = error;
                    provider.unavailableUntil = now() + retry;
                }
                finally {
                    clearTimeout(timer);
                    provider.nextStart = now() + provider.interval;
                }
            }
            throw lastError;
        });
        queue = pending.then(() => { }, () => { });
        const result = pending.finally(() => inflight.delete(path));
        inflight.set(path, result);
        return result;
    };
}
return createAnimeCatalogClient({fetch:safeFetch,fallbackFetch:safeFetch});})();
  "use strict";
async function jikanAnimeSearch(query, limit) {
    const q = query.trim();
    if (q.length < 2)
        return [];
    try {
        const data = await animeCatalogRequest(`/anime?q=${encodeURIComponent(q)}&order_by=popularity&sort=asc&limit=${limit}&sfw=true`);
        return (data.data ?? []).map((a) => {
            const year = a.year ?? (a.aired?.from ? Number(a.aired.from.slice(0, 4)) : null);
            const name = a.title_english?.trim() || a.title?.trim() || "Untitled";
            return {
                malId: a.mal_id,
                format: a.type ?? null,
                name,
                year: year ? String(year) : null,
                poster: a.images?.jpg?.image_url ?? a.images?.jpg?.large_image_url ?? null,
                background: a.trailer?.images?.maximum_image_url ?? null,
                overview: a.synopsis ?? "",
                score: a.score ?? 0,
            };
        });
    }
    catch {
        return [];
    }
}
async function kitsuAnimeSearch(query, limit) {
    const q = query.trim();
    if (q.length < 2)
        return [];
    try {
        const url = `https://kitsu.io/api/edge/anime?filter%5Btext%5D=${encodeURIComponent(q)}&page%5Blimit%5D=${limit}&sort=-userCount`;
        const res = await safeFetch(url, { headers: { Accept: "application/vnd.api+json" } });
        if (!res.ok)
            return [];
        const data = (await res.json());
        return (data.data ?? []).map((a) => {
            const at = a.attributes;
            return {
                malId: 0,
                kitsuId: Number(a.id),
                format: at.subtype ?? null,
                name: at.titles?.en?.trim() || at.canonicalTitle || "Untitled",
                year: at.startDate ? at.startDate.slice(0, 4) : null,
                poster: at.posterImage?.medium ?? at.posterImage?.large ?? null,
                background: at.coverImage?.large ?? null,
                overview: at.synopsis ?? "",
                score: at.averageRating ? Number(at.averageRating) / 10 : 0,
            };
        });
    }
    catch {
        return [];
    }
}
function withSearchTimeout(p, ms, fallback) {
    return Promise.race([p, new Promise((resolve) => setTimeout(() => resolve(fallback), ms))]);
}
async function searchAnime(query, limit = 8) {
    const q = query.trim();
    if (q.length < 2)
        return [];
    const [anilist, jikan, kitsu] = await Promise.all([
        withSearchTimeout(anilistAnimeSearch(q, limit).catch(() => []), 1500, []),
        withSearchTimeout(jikanAnimeSearch(q, limit).catch(() => []), 1200, []),
        withSearchTimeout(kitsuAnimeSearch(q, limit).catch(() => []), 3000, []),
    ]);
    const out = [];
    const seenMal = new Set();
    const seenName = new Set();
    const push = (h) => {
        const nameKey = h.name.toLowerCase().trim();
        if (!nameKey || nameKey === "untitled")
            return;
        if (h.malId && seenMal.has(h.malId))
            return;
        if (seenName.has(nameKey))
            return;
        if (h.malId)
            seenMal.add(h.malId);
        seenName.add(nameKey);
        out.push(h);
    };
    for (const a of anilist) {
        push({
            malId: a.malId ?? 0,
            anilistId: a.anilistId,
            format: a.format,
            name: a.name,
            year: a.year,
            poster: a.poster,
            background: a.background,
            overview: a.overview,
            score: a.score,
        });
    }
    for (const j of jikan)
        push(j);
    for (const k of kitsu)
        push(k);
    return out.slice(0, limit);
}

  "use strict";
function mangaQueries(item, ebook) {
    const normalizeTitle = (title) => title
        .normalize("NFKD")
        .toLocaleLowerCase()
        .replace(/[^\p{L}\p{N}]+/gu, "");
    const queries = [
        item.title,
        ...(item.altTitles ?? []),
        ebook.title,
        ...(ebook.altTitle?.split("|") ?? []),
        ebook.seriesTitle,
    ]
        .map((title) => title?.trim() ?? "")
        .filter(Boolean)
        .filter((title, index, all) => all.findIndex((candidate) => normalizeTitle(candidate) === normalizeTitle(title)) ===
        index)
        .slice(0, 8);
    return queries;
}
function mangaChoices(queries, results) {
    const normalizeTitle = (title) => title
        .normalize("NFKD")
        .toLocaleLowerCase()
        .replace(/[^\p{L}\p{N}]+/gu, "");
    const wanted = new Set(queries.map(normalizeTitle));
    const matches = results.flat();
    const exactMatches = matches.filter((candidate) => wanted.has(normalizeTitle(candidate.title)) ||
        (candidate.altTitle != null && wanted.has(normalizeTitle(candidate.altTitle))));
    const candidates = [
        ...new Map((exactMatches.length ? exactMatches : matches).map((candidate) => [
            candidate.id,
            candidate,
        ])).values(),
    ].slice(0, 3);
    return candidates;
}
function animeRoute(item, matches = []) {
    let result = null;
    const openMeta = value => { result = value; };
    (() => {
        if (item.kind === "anime" && item.anilistId) {
            openMeta({
                id: `anilist:${item.anilistId}`,
                type: "anime",
                name: item.title,
                poster: item.poster,
                description: item.description,
                releaseInfo: item.year ? String(item.year) : undefined,
                animeFormat: item.format,
            }, { exact: true });
            return;
        }
        if (item.kind === "anime") {
            const titleKey = item.title.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");
            const match = matches.find((candidate) => candidate.name.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, "") === titleKey) ?? matches[0];
            if (!match)
                return;
            const id = match.kitsuId
                ? `kitsu:${match.kitsuId}`
                : match.malId
                    ? `mal:${match.malId}`
                    : `anilist:${match.anilistId}`;
            openMeta({
                id,
                type: "anime",
                name: match.name,
                poster: match.poster ?? item.poster,
                background: match.background ?? match.poster ?? item.poster,
                description: match.overview || item.description,
                releaseInfo: match.year ?? (item.year ? String(item.year) : undefined),
                imdbRating: match.score > 0 ? match.score.toFixed(1) : undefined,
                animeFormat: match.format ?? item.format,
            }, { exact: true });
            return;
        }
    })();
    return result;
}

  return {id:"harbor-book-adaptations",name:"Harbor Adaptations",content(input){
    switch(input.operation){
      case "manga-queries":return mangaQueries(input.item,input.book);
      case "manga-choices":return mangaChoices(input.queries,input.results);
      case "anime-route":return animeRoute(input.item,input.matches);
      case "anime-search":return searchAnime(input.query,input.limit??8);
      default:throw new Error("Unknown adaptation operation");
    }
  }};
})();
